self.onmessage=function(a){const{type:e,payload:l}=a.data;if(e==="START"){const{endTime:n}=l;self.timerInterval&&clearInterval(self.timerInterval),self.timerInterval=setInterval(()=>{const t=Math.max(0,n-Date.now()),s=Math.ceil(t/1e3);self.postMessage({type:"TICK",payload:{remainingTime:s}}),t<=0&&(clearInterval(self.timerInterval),self.postMessage({type:"COMPLETE"}))},500)}else e==="STOP"&&self.timerInterval&&(clearInterval(self.timerInterval),self.timerInterval=null)};
